let labTab='metrics',labFeedback='',labOutput=null;
const labNames={metrics:'指标计算',clean:'数据清洗',label:'文本标注',flow:'流程排序',sql:'SQL 查询'};
const rawRows=[{id:'A01',name:' 小林 ',age:24,label:'物流'},{id:'A02',name:'小王',age:null,label:'退款'},{id:'A01',name:' 小林 ',age:24,label:'物流'},{id:'A03',name:'小张',age:-3,label:'物流'},{id:'A04',name:'小陈',age:36,label:'退款'},{id:'A05',name:'小李',age:30,label:'其他'},{id:'A06',name:'小赵 ',age:null,label:'物流'},{id:'A07',name:'小周',age:42,label:'其他'}];
const annotationRows=[['包裹已经发出了，现在到哪了？','物流','已发货后的运输位置查询。'],['我不需要了，请退钱。','退款','明确要求退回款项。'],['有货吗？','其他','库存咨询不属于物流查询或退款。'],['还没收到，但我现在只想退款。','退款','复合诉求按明确的最终行动意图优先。'],['已经发货三天了，什么时候送达？','物流','询问已发货包裹的送达时间。'],['这个怎么弄？','待仲裁','缺少对象与诉求，不能凭空猜标签。'],['这件衣服是什么材质？','其他','商品信息咨询，属于已定义范围外的其他。'],['钱还没退回来，帮我查退款进度。','退款','退款办理进度仍属于退款意图。']];
const flowSteps=['确认业务目标与验收口径','制定采集与标注规范','采集数据并执行质量检查','划分训练、验证、测试集','在训练集拟合预处理并训练模型','用验证集调参和确定阈值','在独立测试集进行最终评估','记录报告并安排上线监控'];
const sqlRows=[{id:'S01',text:'查物流',label:'物流',score:0.92},{id:'S02',text:'请退款',label:null,score:0.65},{id:'S03',text:'问库存',label:'其他',score:0.81},{id:'S04',text:'哪里发货',label:'物流',score:0.48},{id:'S05',text:'退钱进度',label:null,score:0.58},{id:'S06',text:'材质是什么',label:'其他',score:0.95}];
let cleanConfig={dedupe:false,trim:false,invalid:false,missing:'keep'},labelDraft={},flowOrder=[3,0,7,1,5,2,6,4],sqlDraft='SELECT id, text FROM samples WHERE label IS NULL;',metricDraft=['','',''];
if(state.labs.clean?.config)cleanConfig={...cleanConfig,...state.labs.clean.config};if(state.labs.label?.answers)labelDraft=state.labs.label.answers;if(state.labs.flow?.order)flowOrder=state.labs.flow.order;if(state.labs.sql?.query)sqlDraft=state.labs.sql.query;if(state.labs.metrics?.answers)metricDraft=state.labs.metrics.answers;
function tableHTML(rows){if(!rows.length)return '<p class="muted">结果为0行。</p>';let keys=Object.keys(rows[0]);return `<div class="table-scroll"><table><thead><tr>${keys.map(k=>`<th>${esc(k)}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${keys.map(k=>`<td>${r[k]===null?'<i class="muted">NULL</i>':esc(r[k])}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`}
function lab(){let contents={metrics:metricsLab,clean:cleanLab,label:labelLab,flow:flowLab,sql:sqlLab};$('#app').innerHTML=heading('交互实操，做完马上验证。','直接操作小型样本，查看执行结果与评分。这里是教学沙盒，不替代当地考试软件。')+`<div class="tabs">${Object.entries(labNames).map(([id,name])=>`<button class="${labTab===id?'active':''}" onclick="labTab='${id}';labFeedback='';labOutput=null;lab()">${name} ${state.labs[id]?.score===100?'✓':''}</button>`).join('')}</div><section class="card">${contents[labTab]()}</section><div id="labFeedback">${labFeedback}</div><section class="card" style="margin-top:22px"><h2>最近提交成绩</h2><div class="stats" id="labSummary">${Object.entries(labNames).map(([id,name])=>`<div><small>${name}</small><h3>${state.labs[id]?state.labs[id].score+' / 100':'尚未提交'}</h3></div>`).join('')}</div><button onclick="downloadFile('实操学习报告-'+today()+'.json',JSON.stringify(state.labs,null,2))">导出实操报告</button></section>`}
function saveLab(id,score,extra){state.labs[id]={score,at:Date.now(),...extra};activity();save();if($("#labSummary"))$("#labSummary").innerHTML=Object.entries(labNames).map(([key,name])=>`<div><small>${name}</small><h3>${state.labs[key]?state.labs[key].score+" / 100":"尚未提交"}</h3></div>`).join("")}
function feedback(title,html){labFeedback=`<section class="card" style="margin-top:22px"><h2>${title}</h2>${html}</section>`;$('#labFeedback').innerHTML=labFeedback}
function metricsLab(){return `<span class="pill">任务1 · 算法评估</span><h2 style="margin-top:15px">算出模型的“准”与“全”</h2><p>将“投诉”定义为正类。测试结果：TP=60、FP=20、FN=40、TN=880。填写百分数，不要输入%号；保留一位小数。</p>${tableHTML([{实际:'投诉（正）',预测投诉:60,预测非投诉:40},{实际:'非投诉（负）',预测投诉:20,预测非投诉:880}])}<div class="toolbar">${['精确率 Precision','召回率 Recall','F1'].map((s,i)=>`<label>${s}<input aria-label="${s}" id="metric${i}" type="number" min="0" max="100" step="0.1" value="${esc(metricDraft[i])}" oninput="metricDraft[${i}]=this.value" style="display:block;width:150px"></label>`).join('')}</div><button class="primary" onclick="gradeMetrics()">提交并计算</button><details><summary>查看公式提示</summary><p>P=TP/(TP+FP)，R=TP/(TP+FN)，F1=2TP/(2TP+FP+FN)。</p></details>`}
function gradeMetrics(){let vals=[0,1,2].map(i=>$('#metric'+i).value);if(vals.some(v=>v.trim()===''||!Number.isFinite(Number(v))||Number(v)<0||Number(v)>100)){toast('请填写三个0–100之间的有效百分数');return}metricDraft=vals;let expected=[75,60,66.6666667],ok=vals.map((v,i)=>Math.abs(Number(v)-expected[i])<=.11),score=Math.round(ok.filter(Boolean).length/3*100);saveLab('metrics',score,{answers:vals});feedback(`本次 ${score} 分`,['精确率=60/(60+20)=75%','召回率=60/(60+40)=60%','F1=120/(120+20+40)≈66.7%'].map((s,i)=>`<p>${ok[i]?'✓':'○'} ${s}</p>`).join('')+'<p class="note">准确率为94%，但召回率只有60%，仍漏掉了40%的投诉。不要只用总体准确率判断投诉识别效果。</p>')}
function cleanLab(){return `<span class="pill">任务2 · 清洗流水线</span><h2 style="margin-top:15px">按规则真正处理一份数据</h2><p>任务：按id保留首条、清除姓名两端空格、将负年龄转为空值，再用有效年龄中位数填补。教学样本独立使用；真实建模须先划分数据，填补参数只在训练集拟合。</p>${tableHTML(rawRows)}<div class="toolbar"><label><input type="checkbox" id="cleanDedupe" ${cleanConfig.dedupe?'checked':''}> 按id去重</label><label><input type="checkbox" id="cleanTrim" ${cleanConfig.trim?'checked':''}> 姓名去空格</label><label><input type="checkbox" id="cleanInvalid" ${cleanConfig.invalid?'checked':''}> 负年龄转空值</label><label>空值处理 <select id="cleanMissing">${selectOptions([['keep','保留空值'],['zero','填零'],['median','有效年龄中位数']],cleanConfig.missing)}</select></label></div><div class="actions"><button class="primary" onclick="runClean()">执行清洗并检查</button><button onclick="downloadRows('原始清洗样本.csv',rawRows)">下载原始CSV</button></div>`}
function cleanRows(config){let rows=rawRows.map(r=>({...r})),log=[];if(config.dedupe){let seen=new Set();rows=rows.filter(r=>{if(seen.has(r.id))return false;seen.add(r.id);return true});log.push(`按id去重：${rawRows.length}→${rows.length}行`)}if(config.trim){rows.forEach(r=>r.name=r.name.trim());log.push('姓名字段已去除两端空格')}if(config.invalid){let n=0;rows.forEach(r=>{if(r.age!==null&&r.age<0){r.age=null;n++}});log.push(`${n}条负年龄转为空值`)}let fill=null;if(config.missing==='median'){let nums=rows.map(r=>r.age).filter(x=>x!==null&&x>=0).sort((a,b)=>a-b);if(!nums.length)throw Error('无有效年龄，无法计算中位数');fill=nums.length%2?nums[(nums.length-1)/2]:(nums[nums.length/2-1]+nums[nums.length/2])/2}else if(config.missing==='zero')fill=0;if(fill!==null){let n=0;rows.forEach(r=>{if(r.age===null){r.age=fill;n++}});log.push(`填补${n}条空值，填充值=${fill}`)}return {rows,log}}
function runClean(){cleanConfig={dedupe:$('#cleanDedupe').checked,trim:$('#cleanTrim').checked,invalid:$('#cleanInvalid').checked,missing:$('#cleanMissing').value};let out=cleanRows(cleanConfig),checks=[out.rows.length===7,out.rows.every(r=>r.name===r.name.trim()),out.rows.every(r=>r.age>=0&&r.age!==null),['A02','A03','A06'].every(id=>out.rows.find(r=>r.id===id)?.age===33)];let score=checks.filter(Boolean).length*25;labOutput=out.rows;saveLab('clean',score,{config:cleanConfig,log:out.log});feedback(`清洗完成 · ${score} 分`,tableHTML(out.rows)+out.log.map(s=>`<p class="muted">${esc(s)}</p>`).join('')+['去重后7条','姓名无首尾空格','年龄无负数与空值','三个待填补年龄都为33（24、30、36、42的中位数）'].map((s,i)=>`<p>${checks[i]?'✓':'○'} ${s}</p>`).join('')+'<button onclick="downloadRows(\'清洗结果.csv\',labOutput)">下载清洗结果CSV</button>')}
function downloadRows(name,rows){if(!rows?.length){toast('暂无可下载结果');return}let keys=Object.keys(rows[0]);downloadFile(name,'\uFEFF'+[keys,...rows.map(r=>keys.map(k=>r[k]??''))].map(r=>r.map(csvCell).join(',')).join('\r\n'),'text/csv;charset=utf-8')}
function labelLab(){return `<span class="pill">任务3 · 意图标注</span><h2 style="margin-top:15px">根据规范，而不是感觉标注</h2><p class="note">规范：已发货后的运输位置/送达时间→物流；退款申请与进度→退款；明确但不属于前两类→其他；信息不足无法判断→待仲裁。复合诉求以明确的最终行动意图为先。</p>${annotationRows.map((r,i)=>`<div class="module row"><span>${i+1}. ${esc(r[0])}</span><select aria-label="第${i+1}条标签" id="label${i}" onchange="labelDraft[${i}]=this.value">${selectOptions([['','请选择'],...['物流','退款','其他','待仲裁'].map(x=>[x,x])],labelDraft[i]||'')}</select></div>`).join('')}<button class="primary" style="margin-top:20px" onclick="gradeLabels()">提交全部标注</button>`}
function gradeLabels(){let ans=annotationRows.map((_,i)=>$('#label'+i).value);if(ans.some(x=>!x)){toast('请先完成全部8条标注');return}let n=ans.filter((a,i)=>a===annotationRows[i][1]).length,score=Math.round(n/8*100);labelDraft=Object.fromEntries(ans.map((a,i)=>[i,a]));saveLab('label',score,{answers:labelDraft});feedback(`标注一致率 ${score}% · ${n}/8`,annotationRows.map((r,i)=>`<p>${ans[i]===r[1]?'✓':'○'} 第${i+1}条：${r[1]}。${r[2]}</p>`).join('')+'<p class="muted">这里的一致率是与本任务预设规范答案的对比，不代表实际多人标注的Kappa指标。</p>')}
function flowLab(){return `<span class="pill">任务4 · 数据到测试的流程</span><h2 style="margin-top:15px">把流程排成一个可执行顺序</h2><p class="muted">本题按“完成采集质检后再划分，预处理参数只从训练集学习”的教学流程排序。使用上移/下移调整。</p>${flowOrder.map((id,i)=>`<div class="module row"><span><b>${i+1}.</b> ${flowSteps[id]}</span><div><button aria-label="第${i+1}步上移" onclick="moveFlow(${i},-1)" ${i===0?'disabled':''}>↑</button> <button aria-label="第${i+1}步下移" onclick="moveFlow(${i},1)" ${i===flowOrder.length-1?'disabled':''}>↓</button></div></div>`).join('')}<div class="actions"><button class="primary" onclick="gradeFlow()">检查流程</button><button onclick="flowOrder=shuffled(flowOrder);labFeedback='';lab()">重新打乱</button></div>`}
function moveFlow(i,d){let j=i+d;if(j<0||j>=flowOrder.length)return;[flowOrder[i],flowOrder[j]]=[flowOrder[j],flowOrder[i]];labFeedback='';lab()}
function gradeFlow(){let n=flowOrder.filter((id,i)=>id===i).length,score=Math.round(n/8*100);saveLab('flow',score,{order:[...flowOrder]});feedback(`顺序正确 ${n}/8 · ${score}分`,`<ol>${flowSteps.map((s,i)=>`<li>${s} ${flowOrder[i]===i?'✓':''}</li>`).join('')}</ol><p class="note">关键依赖：划分在拟合预处理之前；调参在最终测试之前；测试集用于最终评估，不能反复根据测试结果挑参数。</p>`)}
function sqlLab(){return `<span class="pill">任务5 · 查询沙盒</span><h2 style="margin-top:15px">找出尚未标注的样本</h2><p>任务：从 samples 表中筛选 label 为空的记录，结果至少包含 id 列。输入SQL后会在下表上实际执行。</p>${tableHTML(sqlRows)}<label for="sqlInput">SQL语句</label><textarea id="sqlInput" spellcheck="false" oninput="sqlDraft=this.value">${esc(sqlDraft)}</textarea><button class="primary" onclick="runSql()">运行查询并判分</button><details><summary>支持的SQL范围与示例</summary><p>本沙盒实现教学用SELECT子集：字段投影、COUNT(*)、WHERE（IS NULL / IS NOT NULL / = / &gt; / &gt;= / &lt; / &lt;=），单个条件，不支持连接、子查询、写入或完整数据库语法。</p><pre>SELECT id, text FROM samples WHERE label IS NULL;
SELECT * FROM samples WHERE score &gt;= 0.8;
SELECT COUNT(*) FROM samples WHERE label = '物流';</pre></details>`}
function queryRows(sql){let match=sql.trim().match(/^SELECT\s+(.+?)\s+FROM\s+samples(?:\s+WHERE\s+(.+?))?\s*;?$/i);if(!match)throw Error('仅支持 SELECT 字段 FROM samples [WHERE 单个条件]');let fields=match[1].trim(),cond=(match[2]||'').replace(/;$/,'').trim(),rows=sqlRows.map(r=>({...r}));if(cond){let nullM=cond.match(/^(id|text|label|score)\s+IS\s+(NOT\s+)?NULL$/i),cmp=cond.match(/^(id|text|label|score)\s*(>=|<=|=|>|<)\s*(?:'([^']*)'|(-?\d+(?:\.\d+)?))$/i);if(nullM){let key=nullM[1].toLowerCase();rows=rows.filter(r=>nullM[2]?r[key]!==null:r[key]===null)}else if(cmp){let key=cmp[1].toLowerCase(),op=cmp[2],value=cmp[3]!==undefined?cmp[3]:Number(cmp[4]);rows=rows.filter(r=>{if(r[key]===null)return false;let v=r[key];if(typeof v!==typeof value)throw Error('比较值类型与字段不匹配');return op==='='?v===value:op==='>'?v>value:op==='<'?v<value:op==='>='?v>=value:v<=value})}else throw Error('WHERE条件不受支持；空值请用IS NULL，而不是= NULL')}if(/^COUNT\(\*\)$/i.test(fields))return[{count:rows.length}];let keys=fields==='*'?Object.keys(sqlRows[0]):fields.split(',').map(s=>s.trim().toLowerCase());if(keys.some(k=>!Object.keys(sqlRows[0]).includes(k))||new Set(keys).size!==keys.length)throw Error('字段不存在或重复，可用id、text、label、score');return rows.map(r=>Object.fromEntries(keys.map(k=>[k,r[k]])))}
function runSql(){sqlDraft=$('#sqlInput').value;try{let rows=queryRows(sqlDraft),ids=rows.map(r=>r.id).sort(),correct=ids.length===2&&ids[0]==='S02'&&ids[1]==='S05';labOutput=rows;saveLab('sql',correct?100:0,{query:sqlDraft});feedback(correct?'任务完成 · 100分':'查询已执行，尚未满足任务',tableHTML(rows)+`<p class="note">${correct?'已正确筛选两条未标注记录。':'任务要求结果至少含id，且只包含S02与S05。注意：NULL用IS NULL判断，不是字符串“NULL”。'}</p><button onclick="downloadRows('SQL查询结果.csv',labOutput)">下载查询结果</button>`)}catch(e){feedback('查询未执行',`<p>${esc(e.message)}</p>`)} }

